toggle.bootpaint=function()
    local state=toggle.bootpanel;if not state or state.closed then return end
    local now=tick();local dt=math.max(0,math.min(0.1,now-(state.lastpaint or now-1/60)));state.lastpaint=now
    if state.finished then state.phase=math.max(0,state.phase-dt/0.20)end
    if state.finished and state.phase<=0 then toggle.bootcleanup();return end
    local viewport=ws.CurrentCamera and ws.CurrentCamera.ViewportSize or cam.ViewportSize;local x,y,w,h,logow,logoh=toggle.bootgeometry(viewport);local a=state.phase
    state.bg.Position=Vector2.new(x,y);state.bg.Size=Vector2.new(w,h);state.bg.Transparency=0.84*a;state.bg.Visible=a>0
    state.border.Position=state.bg.Position;state.border.Size=state.bg.Size;state.border.Transparency=0.26*a;state.border.Visible=a>0
    state.logo.Position=Vector2.new(x+(w-logow)/2,y+(h-logoh)/2);state.logo.Size=Vector2.new(logow,logoh);state.logo.Transparency=a;state.logo.Visible=a>0
    if not state.swooshstart then state.swooshstart=now end
    local inset=12;local barwidth=w-inset*2;local phase=((now-state.swooshstart)*1.24)%1
    local travel=barwidth*phase;local sw=math.max(1,math.min(barwidth*0.62,travel/0.64,(barwidth-travel)/0.36));local left=math.max(0,math.min(barwidth-sw,travel-sw*0.64))
    state.swoosh.Position=Vector2.new(x+inset+left,y+h-3);state.swoosh.Size=Vector2.new(sw,2);state.swoosh.Transparency=a*math.min(1,sw/6);state.swoosh.Visible=a>0
end
