    local state=toggle.notifications;local now=tick();local icon=toggle.notificationicon(kind,raw)
    for _,item in ipairs(state.items)do
        local same=item.world==anchor or type(item.world)=="table"and type(anchor)=="table"and math.abs(item.world.X-anchor.X)<1 and math.abs(item.world.Y-anchor.Y)<1 and math.abs(item.world.Z-anchor.Z)<1
        if item.base==raw and same then item.count=(item.count or 1)+1;item.started=now;item.duration=toggle.notifysettings.duration;item.color=tint;item.icon=icon;item.wrapkey=nil;return end
    end
    state.items[#state.items+1]={base=raw,count=1,color=tint,icon=icon,kind=kind,world=anchor,points=points,worldevent=kind=="rake"or kind=="scrap"or kind=="flare"or kind=="trap"or kind=="supply",distanceevent=raw:lower():find("spawned",1,true)~=nil or kind=="rake"and(raw:lower():find("finished teleporting",1,true)~=nil or raw:lower():find("nearby",1,true)~=nil),started=now,duration=toggle.notifysettings.duration,anim=0}
    while #state.items>state.max do table.remove(state.items,1)end
end
