toggle.migratepresetcatalog=function(data)
    if data.preset_name=="default"then local result={};for key,value in pairs(data)do result[key]=value end;result.preset_name="velour";result.preset=toggle.defaultthemeindex;return result end
    if data.preset_catalog_schema==4 then return data end
    local legacy=type(data.preset_name)=="string"and toggle.legacypresetcolors[data.preset_name]
    local selected=legacy and themes[legacy.index];if not selected then return data end
    local result={};for key,value in pairs(data)do result[key]=value end;result.preset_name=selected.name;result.preset=legacy.index;result.preset_catalog_schema=4
    local function original(value,hex)
        if type(value)~="table"then return false end;local c=Color3.fromHex(hex)
        return type(value.r)=="number"and type(value.g)=="number"and type(value.b)=="number"and math.abs(value.r-c.R*255)<1 and math.abs(value.g-c.G*255)<1 and math.abs(value.b-c.B*255)<1
    end
    if original(result.accent,legacy.accent)then result.accent=nil end
    if type(data.theme_colors)=="table"then local colors={};for key,value in pairs(data.theme_colors)do if not legacy[key]or not original(value,legacy[key])then colors[key]=value end end;result.theme_colors=colors end
    return result
end

