toggle.itemdropdownlabel=function(item)
    local kind=toggle.itemdropdownkinds[item.id]
    if not kind then return nil end
    local values={}
    if kind=="shopitem"then return toggle.itemdisplayname(toggle.shopitem().name)end
    local order=kind=="playeritems"and toggle.playeresp.order or kind=="autocollect"and toggle.autocollect.order or toggle.shop.items
    local selected=kind=="playeritems"and toggle.playeresp.selected or kind=="autocollect"and toggle.autocollect.selected or kind=="autobuyitems"and toggle.autobuyitems.selected or toggle.autosellitems.selected
    for _,entry in ipairs(order)do if selected[entry.name]then values[#values+1]=toggle.itemdisplayname(entry.name)end end
    return #values>0 and table.concat(values,", ")or"None"
end
