    local shown=toggle.itemdropdownlabel(item)or item.display or item.value and tostring(item.value)or"";if item.id=="configselect"and string.lower(shown)=="default"then shown="Default"end;if item.kind=="dropdown"and item.id~="configselect"and item.id~="espfontselect"and item.id~="hudfontselect"then if item.id~="presetselect"or not themes[themeindex].custom then shown=toggle.uititle(shown)end end
    if item.kind=="dropdown"then local maxwidth=math.max(0,available or((menustate.w-60)/2-68));if toggle.uiwidth(shown,13)>maxwidth then while #shown>1 and toggle.uiwidth(shown.."..",13)>maxwidth do shown=string.sub(shown,1,-2)end;shown=shown..".."end;return shown end
    if #shown>18 then shown=string.sub(shown,1,16)..".."end;return shown
end
