local function dropdownvalues()
    if dropdownkind=="tablayout"then return{"horizontal","vertical"}end
    if dropdownkind=="trailtype"then return {"Solid Line","Particle Line","Ribbon"}elseif dropdownkind=="trailtargets"then return {"Self","Others","Rake"}elseif dropdownkind=="pathfindertargets"then return {"Scraps","Flares"}elseif dropdownkind=="pathfindermethod"then return {"Legit","Simple"}elseif dropdownkind=="rosterview"then return {"List","Grid"}elseif dropdownkind=="playerbackpack"or dropdownkind=="crateinventorystyle"then return {"Image","Text"}elseif dropdownkind=="oofelements"then return {"Icon","Name","Distance"}elseif dropdownkind=="oof"then return toggle.extra.order elseif dropdownkind=="safespotelements"then return {"Label","Distance"}elseif dropdownkind=="espicons"then return toggle.espiconorder
    elseif dropdownkind=="fonttarget"then return toggle.fonttargetnames
    elseif dropdownkind=="fontfamily"then return fontnames
    elseif dropdownkind=="watermarkelements"then return toggle.watermarkorder
    elseif dropdownkind=="crateelements"or dropdownkind=="flareelements"or dropdownkind=="trapelements"or dropdownkind=="locationelements"then return {"icons"}
    elseif dropdownkind=="terraineditor"then return {"grass","wind","water"}elseif dropdownkind=="posteditor"then return toggle.posteffectnames
    elseif dropdownkind=="scrapedit"then local values={};for i=1,#toggle.scraporder do values[i]=toggle.scraporder[i].label end;return values
    elseif dropdownkind=="locationedit"then local values={};for i=1,#toggle.locationorder do values[i]=toggle.locationorder[i].label end;return values
    elseif dropdownkind=="panelstyle"or dropdownkind=="hudstyle"or dropdownkind=="espstyle"or dropdownkind=="playerstyle"or dropdownkind=="rakestyle"then return {"fluent","compact"}
    elseif dropdownkind=="hudelements"then local values={};for _,entry in ipairs(toggle.hudselectionorder)do values[#values+1]=entry.label end;return values
    elseif dropdownkind=="rakeelements"then return toggle.espelementorder.rake
    elseif dropdownkind=="playerelements"then return toggle.espelementorder.players
    elseif dropdownkind=="espfont"or dropdownkind=="hudfont"then return fontnames
    elseif dropdownkind=="preset"then return toggle.presetorder
    elseif dropdownkind=="distanceposition"then return {"below","above"}
    elseif dropdownkind=="scrapstyle"then return {"tiers","points"}
    elseif dropdownkind=="scrapteleport"then return {"nearest","value","random","nearest to cursor"}
    elseif dropdownkind=="ringshape"then return {"circle","square","triangle","hexagon"}
    elseif dropdownkind=="rgbdirection"then return {"left","right"}
    elseif dropdownkind=="containergrouping"then return {"stacked","ungrouped"}
    elseif dropdownkind=="containerorientation"then return {"horizontal","vertical"}
    elseif dropdownkind=="containerstyle"then return {"fluent","compact"}
    elseif dropdownkind=="poweractivitymode"then return {"activity","always"}
    elseif dropdownkind=="notificationstyle"then return {"fluent","compact"}
    elseif dropdownkind=="notificationposition"then return {"bottom left","bottom right","middle left","middle right"}
    elseif dropdownkind=="tracers"then return toggle.tracers.order
    elseif dropdownkind=="notificationtypes"then return toggle.notifyorder
    elseif dropdownkind=="worldstats"then local values={};for i=1,#toggle.worldorder do values[i]=toggle.worldorder[i].label end;return values
    elseif dropdownkind=="autocollect"then local values={};for i=1,#toggle.autocollect.order do values[i]=toggle.autocollect.order[i].label end;return values
    elseif dropdownkind=="prompts"then local values={};for i=1,#toggle.promptoptionorder do values[i]=toggle.promptoptionorder[i].label end;return values
    elseif dropdownkind=="accentbars"then local values={};for i=1,#toggle.accentbarorder do values[i]=toggle.accentbarorder[i].label end;return values
    elseif dropdownkind=="resets"then local values={};for i=1,#toggle.resetorder do values[i]=toggle.resetorder[i].label end;return values
    elseif dropdownkind=="playeritems"then return toggle.playeresp.names
    elseif dropdownkind=="shopitem"or dropdownkind=="autobuyitems"or dropdownkind=="autosellitems"then toggle.refreshshop(false);return toggle.shop.names
    elseif dropdownkind=="config"then return configslots end
    return {}
end
