toggle.presetpreviewdata=function(index)
    local theme=themes[index];if not theme then return end
    local cached=toggle.presetpreviewcache[index];if cached and cached.theme==theme then return cached.data end
    local asset=not theme.custom and toggle.presetpreviewmodernassets[theme.name];if asset then local data=toggle.iconbase64(asset);toggle.presetpreviewcache[index]={theme=theme,data=data};return data end
    local rows={};local edge=toggle.colormix(theme.card,theme.text,0.22)
    local function coverage(x,y,l,t,r,b,radius)
        local qx=math.abs(x-(l+r)/2)-((r-l+1)/2-radius);local qy=math.abs(y-(t+b)/2)-((b-t+1)/2-radius)
        return clamp(0.5-(math.sqrt(math.max(qx,0)^2+math.max(qy,0)^2)+math.min(math.max(qx,qy),0)-radius),0,1)
    end
    local elements={{29,20,106,25,2,toggle.colormix(theme.text,theme.card,0.12)},{29,36,77,40,2,toggle.colormix(theme.muted,theme.card,0.15)},{149,26,189,38,6,theme.accent}}
    for y=0,63 do local row={string.char(0)};for x=0,207 do
        local c=toggle.colormix(edge,theme.card,coverage(x,y,3,3,204,60,15))
        for _,v in ipairs(elements)do if x>=v[1]-1 and x<=v[3]+1 and y>=v[2]-1 and y<=v[4]+1 then c=toggle.colormix(c,v[6],coverage(x,y,v[1],v[2],v[3],v[4],v[5]))end end
        row[#row+1]=string.char(channel(c.R),channel(c.G),channel(c.B),math.floor(coverage(x,y,0,0,207,63,18)*255+0.5))
    end;rows[#rows+1]=table.concat(row)end
    local data=toggle.iconpng(208,64,table.concat(rows));toggle.presetpreviewcache[index]={theme=theme,data=data};return data
end

toggle.presetgriddata=function(index)
    local theme=themes[index];if not theme then return nil end
    local cached=toggle.presetgridcache[index];if cached and cached.theme==theme then return cached.data end
    local asset=not theme.custom and toggle.presetgridassets[theme.name];local data
    if asset then data=toggle.iconbase64(asset)
    else
        local rows={};local edge=toggle.colormix(theme.bg,theme.text,0.18)
        local function rect(x,y,l,t,r,b,radius)return x>=l and x<=r and y>=t and y<=b and math.max(l+radius-x,0,x-r+radius)^2+math.max(t+radius-y,0,y-b+radius)^2<=radius^2 end
        for y=0,71 do local row={string.char(0)};for x=0,119 do local c=edge;local alpha=rect(x,y,0,0,119,71,6)and 255 or 0
            if rect(x,y,1,1,118,70,5)then c=theme.bg end
            if rect(x,y,5,5,28,66,3)then c=theme.top;if rect(x,y,9,11,23,13,1)then c=theme.text end;if rect(x,y,9,21,23,28,2)then c=theme.select end end
            if rect(x,y,33,5,113,14,3)then c=theme.top end
            for _,left in ipairs({33,75})do if rect(x,y,left,20,left+38,66,3)then c=theme.card;if rect(x,y,left+5,25,left+28,27,1)then c=theme.text elseif rect(x,y,left+5,34,left+21,35,1)then c=theme.muted elseif rect(x,y,left+5,43,left+31,45,1)then c=theme.select;if x<left+23 then c=theme.accent end elseif rect(x,y,left+5,53,left+31,60,2)then c=theme.select;if x>left+12 and x<left+24 and y==56 then c=theme.accent end end end end
            row[#row+1]=string.char(channel(c.R),channel(c.G),channel(c.B),alpha)
        end;rows[#rows+1]=table.concat(row)end;data=toggle.iconpng(120,72,table.concat(rows))
    end
    toggle.presetgridcache[index]={theme=theme,data=data};return data
end

