    local key=slot=="selected"and"selected"or variant=="grid"and index and("grid:"..index)or index;local old=toggle.presetpreviewslots[slot];toggle.presetpreviewslots[slot]=key
    local entry=toggle.presetpreviews[key];if not on then if entry then toggle.setvisible(entry.image,false)end;return end
    if not entry then entry={image=toggle.newicon(slot=="selected"and 121 or 204)};toggle.presetpreviews[key]=entry end
