toggle.resolveplayercharacter=function(player)
    local character=player.Character
    if character and character.Parent and toggle.isa(character,"Model")then return character end
    local fallback=ws:FindFirstChild(player.Name)
    if fallback and fallback.Parent and toggle.isa(fallback,"Model")and fallback:FindFirstChildOfClass("Humanoid")then return fallback end
end
toggle.playerroot=function(character)
    if not character then return nil end
    for _,name in ipairs({"HumanoidRootPart","Torso","UpperTorso"})do local part=character:FindFirstChild(name);if part and part.Parent and toggle.isa(part,"BasePart")then return part end end
end
