            if state.escapedirection then score=score+(d.x*state.escapedirection.x+d.z*state.escapedirection.z)*0.1 end
            if state.active then score=score-math.sqrt((p.X-state.target.X)^2+(p.Z-state.target.Z)^2)*0.0001 end
            if travel<besttravel-0.0001 or math.abs(travel-besttravel)<=0.0001 and score>bestscore then best,bestscore,besttravel=p,score,travel end
        end
    end
    if best then local x,z=best.X-position.X,best.Z-position.Z;local l=math.sqrt(x*x+z*z);state.escapedirection={x=x/l,z=z/l}end
