toggle.safetynext=function(previous,interval)local now=tick();return(previous and previous>0 and previous<=now and now-previous<interval and previous or now)+interval end
toggle.applysafety=function()
    local state=toggle.safetystate
    if not toggle.running or toggle.replacing or toggle.loading or toggle.starting then state.next=0;return false end
    if not toggle.rakeshield and not toggle.autoevadetrap and not state.active then state.lastwrite=nil;return false end
    local now=tick();if now<(state.next or 0)then return false end;state.next=toggle.rakeshield and toggle.safetynext(state.next,math.min(state.interval,state.shieldinterval))or now+state.interval
    local character=lp.Character;local root=character and character:FindFirstChild("HumanoidRootPart");local hum=character and character:FindFirstChildOfClass("Humanoid")
    if not root or not hum or hum.Health<=0 then if state.active then toggle.cancelsafespot("safe spot travel stopped: character unavailable")end;state.character=nil;return false end
    if state.character and not toggle.sameinstance(state.character,character) then toggle.cancelsafespot("safe spot travel stopped after respawn")end;state.character=character
    local position=toggle.position(root);if not toggle.safetyfinite(position)then return false end
    if state.active and state.lastwrite and(position-state.lastwrite).Magnitude>12/stud2m then toggle.cancelsafespot("safe spot travel interrupted by another teleport")end
    local velocity=Vector3.new(0,0,0);local ok,v=pcall(function()return root.AssemblyLinearVelocity end);if ok and toggle.safetyfinite(v)then velocity=v end
    local hazards=toggle.safetyhazards(now,velocity);local step=state.safestepmeters/stud2m
    local escape,threatened,mode=toggle.safetyescape(position,hazards)
    toggle.shieldstate.retreating=threatened
    if threatened then
        
         
         
        if mode=="shield"and now<(state.nextshield or 0)then return false end
        if escape then
             
            local fresh=toggle.safetyhazards(tick(),velocity)
            local moved=toggle.safetywrite(root,character,position,escape,fresh,true,mode)
            if moved then state.nextsafe=tick()+state.safeinterval;if mode=="shield"then state.nextshield=toggle.safetynext(state.nextshield,state.shieldinterval) end end
            return moved
        end
        if mode~="shield"then toggle.safetynotice("Trap escape route is blocked")end;return false
    end
    if not state.active then return false end
    local clearhere=toggle.navwarpsafe(position,position)
    local hx,hz=position.X-state.target.X,position.Z-state.target.Z
    if clearhere and hx*hx+hz*hz<=(1/stud2m)^2 and math.abs(position.Y-state.target.Y)>0.02 then
        local fresh=toggle.safetyhazards(tick(),velocity)
        if not toggle.safetywrite(root,character,position,Vector3.new(position.X,state.target.Y,position.Z),fresh,false)then return false end
        position=toggle.position(root)
    end
    if clearhere and(position-state.target).Magnitude*stud2m<0.4 then
        state.arrivalsince=state.arrivalsince or now
        local settled=now-state.arrivalsince>=0.3
        if settled or now>=(state.nextsafe or 0)then
            local fresh=toggle.safetyhazards(tick(),velocity)
            if not toggle.safetywrite(root,character,position,state.target,fresh,false)then state.arrivalsince=nil;return false end
            state.nextsafe=tick()+state.safeinterval
            if settled then if(state.lastwrite-state.target).Magnitude<=0.02 then toggle.cancelsafespot("arrived at safe spot")else state.arrivalsince=nil end end
            return true
        end
        return false
    end
    state.arrivalsince=nil
    local waypoint=toggle.safespotroute(position)
    if now<(state.nextsafe or 0)or not waypoint then return false end
    local travelto=Vector3.new(waypoint.X,position.Y,waypoint.Z)
    local delta=travelto-position;local length=delta.Magnitude
    local target=length<=step and travelto or position+delta*(step/length)
    local fresh=toggle.safetyhazards(tick(),velocity)
    if not toggle.safetywrite(root,character,position,target,fresh,false)then return false end
    state.nextsafe=tick()+state.safeinterval
    return true
end
 


 
