            local d=ui.draws[spec[1]];toggle.setprop(d,'Size',size);toggle.setprop(d,'Font',toggle.fontvalue('esp'));toggle.setprop(d,'Text',spec[2]);toggle.setprop(d,'Color',tint);toggle.setprop(d,'Transparency',a);toggle.centertext(d,spec[3],y+h/2);toggle.applytextoutline(d,a,tint);toggle.setvisible(d,spec[1]=='distance'and showdistance or spec[1]=='title'and showlabel)
