local function runaction(id)
    if id=="menu"then if toggle.presetcapture then toggle.finishpresetinput(false)end;if toggle.rakenamecapture then toggle.finishrakename(false)end;if toggle.watermark then if not toggle.menu then toggle.menu=true;menustate.minimized=false else menustate.minimized=not menustate.minimized end else toggle.menu=not toggle.menu;menustate.minimized=false end;capture=nil;pickerentry=nil;picker.hexactive=false;dropdownkind=nil;configcapture=false;showmenu()
    elseif id=="esp"then setesp(not toggle.esp)
    elseif id=="hud"then sethud(not toggle.hud)
    elseif id=="collide"then toggle.setclient("antiCollide",not toggle.client.antiCollide)
    elseif id=="door"then toggle.setclient("doorNoCollide",not toggle.client.doorNoCollide)
    elseif id=="spinbot"then toggle.setclient("spinbot",not toggle.client.spinbot)
    elseif id=="thirdperson"then toggle.setthirdperson(not toggle.zoom.thirdperson)
    elseif id=="safespot"then toggle.startsafespot()
    elseif id=="pathfinder"then toggle.setpathfinder(not toggle.pathfinder.enabled)
    elseif id=="evadetrap"then toggle.setautoevadetrap(not toggle.autoevadetrap)
    elseif id=="aura"then toggle.setkillaura(not toggle.killaura)
    elseif id=="quickbuy"or id=="quicksell"then toggle.queueshopaction(id=="quickbuy"and"PurchaseItem"or"SellItem")
    elseif id=="sell"then
        if not toggle.sellenabled then return end;toggle.queueshopaction("SellScraps")
